def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core_pre = v.split('+', 1)[0]
        if '-' in core_pre:
            core, pre = core_pre.split('-', 1)
        else:
            core, pre = core_pre, None

        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts)

        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = []
        else:
            has_pre = 0  # has prerelease sorts before
            pre_ids = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))

        return (major, minor, patch, has_pre, pre_ids)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

